scenarios.example_code:
import { registerRollupSpec } from '@projexlight/sdk-analytics';
await registerRollupSpec({
  tenant_id, name: 'mrr-daily',
  source: 'billing.invoice',
  dimensions: ['plan', 'tenant_id'],
  aggregates: [{ fn: 'sum', column: 'mrr_cents' }],
  refresh_cadence_min: 60,
});

import { publishKpi } from '@projexlight/sdk-analytics';
await publishKpi({
  tenant_id, kpi: 'mau-accounts',
  period: '2026-05',
  value: 18420,
  source_query_hash: '...',
});

import { federatedQuery } from '@projexlight/sdk-analytics';
const rows = await federatedQuery({
  pool_indices: ['pool-a','pool-b','pool-c','pool-d','pool-e'],
  query: 'SELECT pool_id, AVG(dau) FROM events_daily WHERE date >= ?',
  params: ['2026-05-01'],
});

import { extractToLakehouse } from '@projexlight/sdk-analytics';
const job = await extractToLakehouse({
  tenant_id, source_pool: 'pool-app-7',
  source_table: 'analytics.event_inbox',
  target_iceberg_table: 'analytics.tenant_<id>.events',
  period_start, period_end,
});

import { computeCohort } from '@projexlight/sdk-analytics';
const { cohort_id, member_count } = await computeCohort({
  tenant_id, name: 'pro-as-of-last-month',
  definition: { kind: 'sql', query: "SELECT tenant_id FROM billing.invoice WHERE plan='pro' AND period_start='2026-04-01'" },
});
